import React from 'react';

import { CustomSlider } from 'components';
import type { CustomSliderProps } from 'components';

import {
  SliderAvailableZone,
  SliderTrack,
  SliderTrackWrapper,
} from '../../TimePeriodSelector.styles';
import type { SliderPositions } from '../../utils';
import { SliderTrackLayers } from '../SliderTrackLayers';

interface TimePeriodSliderTrackProps {
  readonly positions: SliderPositions;
  readonly preview?: SliderPositions | null;
  readonly sliderProps?: CustomSliderProps;
  readonly isDragging?: boolean;
  readonly cursor?: 'pointer' | 'grab';
  readonly showHandle?: boolean;
}

export function TimePeriodSliderTrack({
  positions,
  preview = null,
  sliderProps,
  isDragging = false,
  cursor = 'grab',
  showHandle = true,
}: TimePeriodSliderTrackProps) {
  return (
    <SliderTrackWrapper
      $noDrag={!sliderProps}
      style={
        sliderProps
          ? {
              cursor: isDragging ? 'grabbing' : cursor,
              userSelect: 'none',
            }
          : undefined
      }
    >
      <SliderTrack>
        <SliderAvailableZone
          style={{ width: `${positions.availableWidth}%` }}
        />
        <SliderTrackLayers
          positions={positions}
          preview={preview}
          showHandle={showHandle}
        />
        {sliderProps && (
          <CustomSlider {...sliderProps} visualMode="inputOnly" />
        )}
      </SliderTrack>
    </SliderTrackWrapper>
  );
}
